B.a88=new A.bL(101,1,"Aadhaaram Naaku Aadhaaram","\u0c06\u0c27\u0c3e\u0c30\u0c02 \u0c28\u0c3e\u0c15\u0c41 \u0c06\u0c27\u0c3e\u0c30\u0c02","","Bethel Worship","Bonigala Babu Rao","assets/church.jpg",10,"Songs of Zion",B.cc,null,null,null)
